import random
from collections import defaultdict
from collections.abc import Callable
from unittest import TestCase

from tqdm import tqdm, trange

from graphtage.fibonacci import FibonacciHeap, HeapNode, MaxFibonacciHeap


class TestFibonacciHeap(TestCase):
    @classmethod
    def setUpClass(cls):
        cls.random_list: list[int] = [random.randint(0, 10000) for _ in range(10000)]
        cls.sorted_list: list[int] = sorted(cls.random_list)

    def test_duplicate_items(self):
        heap = FibonacciHeap()
        test_list = [2, 1, 2]
        for i in test_list:
            heap.push(i)
        heap_sorted = [heap.pop() for _ in range(len(test_list))]
        self.assertEqual(sorted(test_list), heap_sorted)

    def random_heap(self) -> FibonacciHeap[int, int]:
        heap: FibonacciHeap[int, int] = FibonacciHeap()
        for rand_int in self.random_list:
            heap.push(rand_int)
        return heap

    def random_max_heap(self, key: Callable[[int], int] | None = None) -> MaxFibonacciHeap[int, int]:
        heap: FibonacciHeap[int, int] = MaxFibonacciHeap(key=key)
        for rand_int in self.random_list:
            heap.push(rand_int)
        return heap

    def test_fibonacci_heap(self):
        heap = self.random_heap()
        heap_sorted = [heap.pop() for _ in range(len(self.random_list))]
        self.assertEqual(self.sorted_list, heap_sorted)

    def test_max_fibonacci_heap(self):
        heap = self.random_max_heap()
        heap_sorted = [heap.pop() for _ in range(len(self.random_list))]
        self.assertEqual(list(reversed(self.sorted_list)), heap_sorted)

    def test_max_fibonacci_heap_with_key(self):
        heap = self.random_max_heap(key=lambda i: -i)
        heap_sorted = [heap.pop() for _ in range(len(self.random_list))]
        self.assertEqual(self.sorted_list, heap_sorted)

    def test_node_traversal(self):
        heap = self.random_heap()
        self.assertEqual(sum(1 for _ in heap.nodes()), len(heap))

    def test_manual_node_deletion(self):
        heap = self.random_heap()
        for i in trange(len(self.random_list)//20):
            random_node: HeapNode[int, int] = random.choice(list(heap.nodes()))
            heap.decrease_key(random_node, -1)
            heap.pop()
            random_node.deleted = True
            self.assertEqual(len(heap), len(self.random_list) - i - 1)

    def test_node_deletion(self):
        heap = self.random_heap()
        for i in trange(len(self.random_list)//20):
            random_node: HeapNode[int, int] = random.choice(list(heap.nodes()))
            heap.remove(random_node)
            self.assertEqual(len(heap), len(self.random_list) - i - 1)

    def test_decrease_key(self):
        heap = self.random_heap()
        nodes_by_value: dict[int, set[HeapNode[int, int]]] = defaultdict(set)
        for node in heap.nodes():
            nodes_by_value[node.key].add(node)
        changes: dict[int, int] = {}
        for _ in trange(len(self.random_list)//20):
            while True:
                random_sorted_index = random.randint(0, len(self.random_list) - 1)
                if random_sorted_index not in changes:
                    break
            random_node: HeapNode[int, int] = next(iter(nodes_by_value[self.sorted_list[random_sorted_index]]))
            self.assertEqual(random_node.key, self.sorted_list[random_sorted_index])
            if random_node.key <= 0:
                continue
            new_key = random.randint(0, random_node.key - 1)
            nodes_by_value[random_node.key].remove(random_node)
            nodes_by_value[new_key].add(random_node)
            changes[random_sorted_index] = new_key
            heap.decrease_key(random_node, new_key)
        updated_list = []
        for i, expected in enumerate(self.sorted_list):
            if i in changes:
                updated_list.append(changes[i])
            else:
                updated_list.append(expected)
        expected_list = sorted(updated_list)
        for expected in tqdm(expected_list):
            node = heap.min_node
            heap.pop()
            self.assertEqual(node.key, expected)

"""A module for solving a search problem in an iteratively revealed search space.

**Given:** an iterator that yields an unknown but finite number of integer range objects, *e.g.*, ``[100, 200]``,
``[50, 1000]``, ``[60, 500]``, …. Each integer range object has a member function that is guaranteed to tighten the
bounds of the range, such that the range monotonically shrinks and converges toward a specific number (*i.e.*, it
conforms to the :class:`graphtage.bounds.Bounded` protocol). For example, ``[100, 200].tighten()`` →
``[150, 160].tighten()`` → ``[150, 155].tighten()`` → ``[153, 153]`` → ``153``. Each object might have a different
tighten function; we cannot make any assumptions about the rate of convergence, other than that the bounds are
guaranteed to shrink with each call to ``tighten()``.

**Goal:** Create the most computationally efficient algorithm to determine the range object that converges to the
smallest integer (*i.e.*, with the fewest possible tightenings).

"""

from collections.abc import Iterator
from typing import Generic, TypeVar

from .bounds import NEGATIVE_INFINITY, POSITIVE_INFINITY, Bounded, Range
from .fibonacci import FibonacciHeap, HeapNode

B = TypeVar('B', bound=Bounded)


class IterativeTighteningSearch(Bounded, Generic[B]):
    """Implementation of iterative tightening search on a given sequence of :class:`graphtage.bounds.Bounded` objects.

    The search class itself is :class:`graphtage.bounds.Bounded`, with bounds on the value of the optimal solution.
    Each call to :meth:`IterativeTighteningSearch.tighten_bounds` will improve these bounds, if possible.

    """
    def __init__(self,
                 possibilities: Iterator[B],
                 initial_bounds: Range | None = None):
        """Initializes the search.

        Args:
            possibilities: An iterator yielding :class:`graphtage.bounded.Bounded` objects over which to search.
            initial_bounds: Bounds on the optimal solution, if known. Having good initial bounds can greatly speed up
                the search. However, if the initial bounds are incorrect (*i.e.*, if the true optimal solution lies
                outside of :obj:`initial_bounds`, then the resulting solution may be incorrect.

        """

        def get_range(bounded: Bounded) -> Range:
            return bounded.bounds()

        self._unprocessed: Iterator[B] = possibilities

        # Heap to track the ranges with the lowest upper bound
        self._untightened: FibonacciHeap[B, Range] = FibonacciHeap(key=get_range)

        # Fully tightened (`definitive`) ranges, sorted by increasing bound
        self._tightened: FibonacciHeap[B, Range] = FibonacciHeap(key=get_range)

        if initial_bounds is None:
            self.initial_bounds = Range(NEGATIVE_INFINITY, POSITIVE_INFINITY)
        else:
            self.initial_bounds = initial_bounds

    def __bool__(self):
        """Returns whether or not this search's bounds are :meth:`definitive<graphtage.bounds.Range.definitive>`."""
        return bool(self._unprocessed or ((self._untightened or self._tightened) and not self.bounds().definitive()))

    @property
    def best_match(self) -> B | None:
        """Returns the best solution the search has thus found.

         Returns:
            B | None: The best solution the search has thus found, or :const:`None` if it has not yet found a
            feasible solution.

        """
        if self._unprocessed is not None or not (self._untightened or self._tightened):
            return None
        elif self._tightened and self._untightened:
            if self._untightened.peek().bounds() < self._tightened.peek().bounds():
                return self._untightened.peek()
            else:
                return self._tightened.peek()
        elif self._tightened:
            return self._tightened.peek()
        else:
            return self._untightened.peek()

    def remove_best(self) -> B | None:
        """Removes and returns the current best solution found by the search, if one exists.

        This enables one to iteratively sort the input sequence. However, this function is only guaranteed to return
        the globally optimal item if :meth:`IterativeTighteningSearch.goal_test` returns :const:`True`. Therefore,
        to generate a total ordering over the input sequence, you should tighten bounds until the goal is reached before
        each call to this function::

            while search.tighten_bounds():
                while not search.goal_test() and search.tighten_bounds():
                    pass
                if search.goal_test():
                    yield search.remove_best()
            while search.goal_test():
                yield search.remove_best()

        However, if your goal is to produce a total ordering, :func:`graphtage.bounds.sort` is more efficient.

        """
        if self._unprocessed is not None or not (self._untightened or self._tightened):
            return None
        elif self._tightened and self._untightened:
            if self._untightened.peek().bounds() < self._tightened.peek().bounds():
                heap = self._untightened
            else:
                heap = self._tightened
        elif self._tightened:
            heap = self._tightened
        else:
            heap = self._untightened
        return heap.pop()

    def search(self) -> B:
        """Finds and returns the smallest item, fully tightened.

        This is equivalent to::

            while self.tighten_bounds():
                pass
            return self.best_match

        """
        while self.tighten_bounds():
            pass
        return self.best_match

    def _nodes(self) -> Iterator[HeapNode[B, Range]]:
        yield from self._untightened.nodes()
        yield from self._tightened.nodes()

    def bounds(self) -> Range:
        if self.best_match is None:
            return self.initial_bounds
        else:
            if self._unprocessed is None and (self._untightened or self._tightened):
                lb = POSITIVE_INFINITY
                for node in self._nodes():
                    if not node.deleted:
                        lb = min(node.key.lower_bound, lb)
                if lb == POSITIVE_INFINITY or lb < self.initial_bounds.lower_bound:
                    lb = self.initial_bounds.lower_bound
            else:
                lb = self.initial_bounds.lower_bound
            return Range(min(lb, self.best_match.bounds().upper_bound), self.best_match.bounds().upper_bound)

    def _delete_node(self, node: HeapNode[B, Range]):
        self._untightened.decrease_key(node, Range(NEGATIVE_INFINITY, NEGATIVE_INFINITY))
        self._untightened.pop()
        node.deleted = True

    def _update_bounds(self, node: HeapNode[B, Range]):
        if self.best_match is not None \
                and self.best_match != node.item \
                and self.best_match.bounds().dominates(node.item.bounds()):
            self._delete_node(node)
            return
        elif self.initial_bounds.dominates(node.item.bounds()):
            self._delete_node(node)
            return
        bounds: Range = node.item.bounds()
        if bounds.definitive():
            self._delete_node(node)
            self._tightened.push(node.item)
        elif bounds.lower_bound > node.key.lower_bound:
            # The lower bound increased, so we need to remove and re-add the node
            # because the Fibonacci heap only permits making keys smaller
            self._untightened.decrease_key(node, Range(NEGATIVE_INFINITY, NEGATIVE_INFINITY))
            self._untightened.pop()
            self._untightened.push(node.item)

    def goal_test(self) -> bool:
        """Returns whether :meth:`best_match<IterativeTighteningSearch.best_match>` is the optimal solution."""
        if self._unprocessed is not None:
            return False
        best = self.best_match
        return best is not None and best.bounds().dominates(self.bounds())

    def tighten_bounds(self) -> bool:
        starting_bounds = self.bounds()
        while True:
            if self._unprocessed is not None:
                try:
                    next_best: B = next(self._unprocessed)
                    if self.initial_bounds.lower_bound > NEGATIVE_INFINITY and \
                            self.initial_bounds.lower_bound >= next_best.bounds().upper_bound:
                        # We can't do any better than this choice!
                        self._unprocessed = None
                        self._untightened.clear()
                        self._tightened.clear()
                        if next_best.bounds().definitive():
                            self._tightened.push(next_best)
                        else:
                            self._untightened.push(next_best)
                        return True
                    if starting_bounds.dominates(next_best.bounds()) or \
                            (self.best_match is not None
                             and self.best_match.bounds().dominates(next_best.bounds())) or \
                            self.initial_bounds.dominates(next_best.bounds()):
                        # No need to add this new edit if it is strictly worse than the current best!
                        pass
                    if next_best.bounds().definitive():
                        self._tightened.push(next_best)
                    else:
                        self._untightened.push(next_best)
                except StopIteration:
                    self._unprocessed = None
            tightened = False
            if self._untightened:
                if self._unprocessed is None:
                    if len(self._untightened) == 1:
                        untightened = self._untightened.peek()
                        if untightened.tighten_bounds() and untightened.bounds().definitive():
                            self._untightened.clear()
                            self._tightened.push(untightened)
                    if self.goal_test():
                        best = self.best_match
                        self._untightened.clear()
                        self._tightened.clear()
                        ret = best.tighten_bounds()
                        if best.bounds().definitive():
                            self._tightened.push(best)
                        else:
                            self._untightened.push(best)
                        assert self.best_match == best
                        return ret
                for node in list(self._untightened.min_node):
                    if node.deleted:
                        continue
                    tightened = node.item.tighten_bounds()
                    if tightened:
                        self._update_bounds(node)
                        break
            if starting_bounds.lower_bound < self.bounds().lower_bound \
                    or starting_bounds.upper_bound > self.bounds().upper_bound:
                return True
            elif self._unprocessed is None and not tightened:
                return False

"""A pure Python implementation of a `Fibonacci Heap`_.

Many of the algorithms in Graphtage only require partially sorting collections, so we can get a speedup from using a
Fibonacci Heap that has amortized constant time insertion.

.. _Fibonacci Heap:
    https://en.wikipedia.org/wiki/Fibonacci_heap

"""

from collections.abc import Callable, Iterator
from typing import Generic, TypeVar

T = TypeVar('T')
Key = TypeVar('Key')
DefaultKey = object()


class HeapNode(Generic[T, Key]):
    """A node in a :class:`FibonacciHeap`."""
    def __init__(self, item: T, key: Key = DefaultKey):
        """Initializes a Fibonacci heap node.

        Args:
            item: The heap item associated with the node.
            key: An optional key to use for the item in sorting. If omitted, the item itself will be used.

        """
        self.item: T = item
        """The item associated with this heap node."""
        if id(key) == id(DefaultKey):
            key = item
        self.key: Key = key
        """The key to be used when sorting this heap node."""
        self.parent: HeapNode[T, Key] | None = None
        """The node's parent."""
        self.child: HeapNode[T, Key] | None = None
        """The node's child."""
        self.left: HeapNode[T, Key] = self
        """The left sibling of this node, or :obj:`self` if it has no left sibling."""
        self.right: HeapNode[T, Key] = self
        """The right sibling of this node, or :obj:`self` if it has no left sibling."""
        self.degree: int = 0
        """The degree of this node (*i.e.*, the number of its children)."""
        self.mark: bool = False
        """The node's marked state."""
        self.deleted: bool = False
        """Whether the node has been deleted.

        This is to prevent nodes from being manipulated after they have been removed from a heap.

        Warning:
            Do not set :attr:`HeapNode.deleted` to :const:`True` unless the node has already been removed from the heap.

        """

    def add_child(self, node):
        """Adds a child to this heap node, incrementing its degree."""
        assert node != self
        if self.child is None:
            self.child = node
        else:
            node.right = self.child.right
            node.left = self.child
            self.child.right.left = node
            self.child.right = node
        self.degree += 1

    def remove_child(self, node):
        """Removes a child from this heap node, decrementing its degree."""
        assert self.child is not None
        if self.child == self.child.right:
            self.child = None
        elif self.child == node:
            self.child = node.right
            node.right.parent = self
        node.left.right = node.right
        node.right.left = node.left
        self.degree -= 1

    @property
    def siblings(self) -> Iterator['HeapNode[T, Key]']:
        """Iterates over this node's siblings.

        Equivalent to::

            node = self.right
            while node != self:
                yield node
                node = node.right

        """
        node = self.right
        while node != self:
            yield node
            node = node.right

    @property
    def children(self) -> Iterator['HeapNode[T, Key]']:
        """Iterates over this node's children.

        Equivalent to::

            if self.child is not None:
                yield self.child
                yield from self.child.siblings

        """
        assert (self.degree == 0 and self.child is None) or (self.degree == 1 + sum(1 for _ in self.child.siblings))
        if self.child is not None:
            yield self.child
            yield from self.child.siblings

    def __iter__(self) -> Iterator['HeapNode[T, Key]']:
        """Iterates over all of this node's descendants, including itself."""
        yield self
        if self.child:
            yield from iter(self.child)
        node = self.right
        while node != self:
            yield node
            if node.child is not None:
                yield from iter(node.child)
            node = node.right

    def __lt__(self, other):
        return (self.deleted and not other.deleted) or self.key < other.key

    def __le__(self, other):
        return self < other or self.key == other.key

    def __eq__(self, other):
        return id(self) == id(other)

    def __hash__(self):
        return hash(self.item)

    def __repr__(self):
        return f"{self.__class__.__name__}(item={self.item!r}, key={self.key!r})"


class FibonacciHeap(Generic[T, Key]):
    """A Fibonacci Heap."""
    def __init__(self, key: Callable[[T], Key] | None = None):
        """Initializes a Fibonacci heap.

        Args:
            key: An optional function that accepts an item and returns the key to be used for comparing that item.
                If omitted, it is equivalent to::

                    lambda item: item

        """
        if key is None:
            self.key = lambda a: a
            """The function to extract comparison keys from items."""
        else:
            self.key: Callable[[T], Key] = key
        self._min: HeapNode[T, Key] | None = None
        self._root: HeapNode[T, Key] | None = None
        self._n: int = 0

    def clear(self):
        """Removes all items from this heap."""
        self._min = None
        self._root = None
        self._n = 0

    def peek(self) -> T:
        """Returns the smallest element of the heap without removing it.

        Returns:
            T: The smallest element of the heap.

        """
        while self._min is not None and self._min.deleted:
            self._extract_min()
        return self._min.item

    def remove(self, node: HeapNode[T, Key]):
        """Removes the given node from this heap.

        Args:
            node: The node to be removed.

        Warning:
            This function assumes that the provided node is actually a member of this heap. It also assumes (but does
            not check) that :attr:`node.deleted <HeapNode.deleted>` is :const:`False`. If either of these assumptions
            is incorrect, it will lead to undefined behavior and corruption of the heap.

        """
        node.deleted = True
        y = node.parent
        if y is not None and node < y:
            self._cut(node, y)
            self._cascading_cut(y)
        self._min = node
        self._extract_min()

    @property
    def min_node(self) -> HeapNode[T, Key]:
        """Returns the heap node associated with the smallest item in the heap, without removing it."""
        return self._min

    @property
    def _roots(self) -> Iterator[HeapNode[T, Key]]:
        if self._root is not None:
            yield self._root
            yield from self._root.siblings

    def __len__(self):
        return self._n

    def __bool__(self):
        return self._n > 0

    def __iter__(self) -> Iterator[T]:
        for node in self._root:
            yield node.item

    def nodes(self) -> Iterator[HeapNode[T, Key]]:
        """Iterates over all of the heap nodes in this heap."""
        if self._root is None:
            return
        yield from iter(self._root)

    def _extract_min(self) -> HeapNode[T, Key]:
        z = self._min
        if z is not None:
            if z.child is not None:
                for child in list(z.children):
                    self._append_root(child)
                    child.parent = None
            self._remove_root(z)
            if z == z.right:
                self._min = self._root = None
            else:
                self._min = z.right
                self._consolidate()
            self._n -= 1
        return z

    def push(self, item: T) -> HeapNode[T, Key]:
        """Adds a new item to this heap.

        Returns:
            HeapNode[T, Key]: The heap node created to store the new item.

        """
        node = HeapNode(item=item, key=self.key(item))
        node.left = node.right = node
        self._append_root(node)
        if self._min is None or node < self._min:
            self._min = node
        self._n += 1
        return node

    def decrease_key(self, x: HeapNode[T, Key], k: Key):
        """Decreases the key value associated with the given node.

        Args:
            x: The node to modify.
            k: The new key value.

        Raises:
            ValueError: If :attr:`x.key <HeapNode.key>` is less than :obj:`k`.

        """
        if x.key < k:
            raise ValueError(f"The key can only decrease! New key {k!r} > old key {x.key!r}.")
        x.key = k
        y = x.parent
        if y is not None and x < y:
            self._cut(x, y)
            self._cascading_cut(y)
        if x < self._min:
            self._min = x

    def __add__(self, other):
        if not other:
            return self
        elif not self:
            return other
        merged = FibonacciHeap(key=self.key)
        merged._root, merged._min = self._root, self._min
        merged.key = self.key
        last = other._root.left
        other._root.left = merged._root.left
        merged._root.left.right = other._root
        merged._root.left = last
        merged._root.left.right = merged._root
        if other._min < merged._min:
            merged._min = other._min
        merged._n = self._n + other._n
        return merged

    def _cut(self, x: HeapNode[T, Key], y: HeapNode[T, Key]):
        y.remove_child(x)
        self._append_root(x)
        x.parent = None
        x.mark = False

    def _cascading_cut(self, y: HeapNode[T, Key]):
        z = y.parent
        if z is not None:
            if y.mark is False:
                y.mark = True
            else:
                self._cut(y, z)
                self._cascading_cut(z)

    def _consolidate(self):
        a = [None] * self._n
        for x in list(self._roots):
            d = x.degree
            while a[d] is not None:
                y = a[d]
                if y < x:
                    x, y = y, x
                self._link(y, x)
                a[d] = None
                d += 1
            a[d] = x
        for i in range(0, len(a)):
            if a[i] is not None and a[i] <= self._min:
                self._min = a[i]

    def _link(self, y: HeapNode[T, Key], x: HeapNode[T, Key]):
        self._remove_root(y)
        y.left = y.right = y
        x.add_child(y)
        y.parent = x
        y.mark = False

    def _append_root(self, node: HeapNode[T, Key]):
        if self._root is None:
            self._root = node
        else:
            node.right = self._root.right
            node.left = self._root
            self._root.right.left = node
            self._root.right = node

    def _remove_root(self, node: HeapNode[T, Key]):
        if node == self._root:
            self._root = node.right
        node.left.right = node.right
        node.right.left = node.left

    def pop(self) -> T:
        """Returns and removes the smallest item from this heap."""
        while self._min is not None and self._min.deleted:
            self._extract_min()
        return self._extract_min().item


class ReversedComparator(Generic[Key]):
    """A wrapper that reverses the semantics of its comparison operators."""
    def __init__(self, key: Key):
        self.key = key

    def __lt__(self, other):
        return self.key > other.key

    def __le__(self, other):
        return self.key >= other.key

    def __eq__(self, other):
        return self.key == other.key

    def __hash__(self):
        return hash(self.key)


class MaxFibonacciHeap(Generic[T, Key], FibonacciHeap[T, ReversedComparator[Key]]):
    """A Fibonacci Heap that yields items in decreasing order, using a :class:`ReversedComparator`."""
    def __init__(self, key: Callable[[T], Key] | None = None):
        if key is None:
            def key(n: T):
                return n
        super().__init__(key=lambda n: ReversedComparator(key(n)))

